import{_ as l,a0 as o,w as p,s as h,ao as d,I as t,x as e,a1 as a,A as n}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const E=JSON.parse('{"title":"Windows 下 Emacs 中的 zsh shell | LCTT x X-CMD","titleTemplate":false,"description":"Windows 下 Emacs 中的 zsh shell | LCTT (201903) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Windows 下 Emacs 中的 zsh shell | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Windows 下 Emacs 中的 zsh shell | LCTT (201903) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201903/20170519 zsh shell inside Emacs on Windows","title":"Windows 下 Emacs 中的 zsh shell","tag":"201903","desc":""},"relativePath":"201903/20170519 zsh shell inside Emacs on Windows.md","filePath":"[post].md"}'),c={name:"201903/20170519 zsh shell inside Emacs on Windows.md"};function r(g,s,u,m,k,b){const i=o("Link");return p(),h("div",null,[s[15]||(s[15]=d(`<h1 id="windows-下-emacs-中的-zsh-shell" tabindex="-1">Windows 下 Emacs 中的 zsh shell <a class="header-anchor" href="#windows-下-emacs-中的-zsh-shell" aria-label="Permalink to “Windows 下 Emacs 中的 zsh shell”">​</a></h1><p><img src="https://www.onwebsecurity.com//images/zsh-shell-inside-emacs-on-windows.png" alt="zsh shell inside Emacs on Windows"></p><p>运行跨平台 shell（例如 Bash 或 zsh）的最大优势在于你能在多平台上使用同样的语法和脚本。在 Windows 上设置（替换）shell 挺麻烦的，但所获得的回报远远超出这小小的付出。</p><p>MSYS2 子系统允许你在 Windows 上运行 Bash 或 zsh 之类的 shell。使用 MSYS2 很重要的一点在于确保搜索路径都指向 MSYS2 子系统本身：存在太多依赖关系了。</p><p>MSYS2 安装后默认的 shell 就是 Bash；zsh 则可以通过包管理器进行安装：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>pacman -Sy zsh</span></span></code></pre></div><p>通过修改 <code>etc/passwd</code> 文件可以设置 zsh 作为默认 shell，例如：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>mkpasswd -c | sed -e &#39;s/bash/zsh/&#39; | tee -a /etc/passwd</span></span></code></pre></div><p>这会将默认 shell 从 bash 改成 zsh。</p><p>要在 Windows 上的 Emacs 中运行 zsh ，需要修改 <code>shell-file-name</code> 变量，将它指向 MSYS2 子系统中的 zsh 二进制文件。该二进制 shell 文件在 Emacs <code>exec-path</code> 变量中的某个地方。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(setq shell-file-name (executable-find &quot;zsh.exe&quot;))</span></span></code></pre></div><p>不要忘了修改 Emacs 的 <code>PATH</code> 环境变量，因为 MSYS2 路径应该先于 Windows 路径。接上一个例子，假设 MSYS2 安装在 <code>c:\\programs\\msys2</code> 中，那么执行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>(setenv &quot;PATH&quot; &quot;C:\\\\programs\\\\msys2\\\\mingw64\\\\bin;C:\\\\programs\\\\msys2\\\\usr\\\\local\\\\bin;C:\\\\programs\\\\msys2\\\\usr\\\\bin;C:\\\\Windows\\\\System32;C:\\\\Windows&quot;)</span></span></code></pre></div><p>在 Emacs 配置文件中设置好这两个变量后，在 Emacs 中运行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>M-x shell</span></span></code></pre></div><p>应该就能看到熟悉的 zsh 提示符了。</p><p>Emacs 的终端设置（eterm）与 MSYS2 的标准终端设置（xterm-256color）不一样。这意味着某些插件和主题（提示符）可能不能正常工作 - 尤其在使用 oh-my-zsh 时。</p><p>检测 zsh 否则在 Emacs 中运行很简单，使用变量 <code>$INSIDE_EMACS</code>。</p><p>下面这段代码片段取自 <code>.zshrc</code>（当以交互式 shell 模式启动时会被加载），它会在 zsh 在 Emacs 中运行时启动 git 插件并更改主题：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># Disable some plugins while running in Emacs</span></span>
<span class="line"><span>if [[ -n &quot;$INSIDE_EMACS&quot; ]]; then</span></span>
<span class="line"><span>  plugins=(git)</span></span>
<span class="line"><span>  ZSH_THEME=&quot;simple&quot;</span></span>
<span class="line"><span>else</span></span>
<span class="line"><span>  ZSH_THEME=&quot;compact-grey&quot;</span></span>
<span class="line"><span>fi</span></span></code></pre></div><p>通过在本地 <code>~/.ssh/config</code> 文件中将 <code>INSIDE_EMACS</code> 变量设置为 <code>SendEnv</code> 变量……</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Host myhost</span></span>
<span class="line"><span>SendEnv INSIDE_EMACS</span></span></code></pre></div><p>……同时在 ssh 服务器的 <code>/etc/ssh/sshd_config</code> 中设置为 <code>AcceptEnv</code> 变量……</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>AcceptEnv LANG LC_* INSIDE_EMACS</span></span></code></pre></div><p>……这使得在 Emacs shell 会话中通过 ssh 登录另一个运行着 zsh 的 ssh 服务器也能工作的很好。当在 Windows 下的 Emacs 中的 zsh 上通过 ssh 远程登录时，记得使用参数 <code>-t</code>，<code>-t</code> 参数会强制分配伪终端（之所以需要这样，时因为 Windows 下的 Emacs 并没有真正的 tty）。</p><p>跨平台，开源真是个好东西……</p><hr>`,27)),t("p",null,[s[1]||(s[1]=e("via: ",-1)),a(i,{href:"https://www.onwebsecurity.com/configuration/zsh-shell-inside-emacs-on-windows.html"},{default:n(()=>[...s[0]||(s[0]=[e("https://www.onwebsecurity.com/configuration/zsh-shell-inside-emacs-on-windows.html",-1)])]),_:1})]),t("p",null,[s[6]||(s[6]=e("作者：",-1)),a(i,{href:"https://www.onwebsecurity.com/"},{default:n(()=>[...s[2]||(s[2]=[e("Peter Mosmans",-1)])]),_:1}),s[7]||(s[7]=e(" 选题：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 译者：",-1)),a(i,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[4]||(s[4]=[e("lujun9972",-1)])]),_:1}),s[9]||(s[9]=e(" 校对：",-1)),a(i,{href:"https://github.com/wxy"},{default:n(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(i,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原创编译，",-1)),a(i,{href:"https://linux.cn/"},{default:n(()=>[...s[11]||(s[11]=[e("Linux中国",-1)])]),_:1}),s[14]||(s[14]=e(" 荣誉推出",-1))])])}const C=l(c,[["render",r]]);export{E as __pageData,C as default};
